/**
 * Returned by `Core::new` when the supplied identity secret doesn't parse —
 * the one thing that can go wrong before the background thread even starts.
 */
sealed class CoreInitException: kotlin.Exception() {
    
    class BadIdentity(
        
        val `detail`: kotlin.String
        ) : CoreInitException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class ThreadSpawn(
        
        val `detail`: kotlin.String
        ) : CoreInitException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class DbOpen(
        
        val `detail`: kotlin.String
        ) : CoreInitException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreInitException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreInitException = FfiConverterTypeCoreInitError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreInitError : FfiConverterRustBuffer<CoreInitException> {
    override fun read(buf: ByteBuffer): CoreInitException {
        

        return when(buf.getInt()) {
            1 -> CoreInitException.BadIdentity(
                FfiConverterString.read(buf),
                )
            2 -> CoreInitException.ThreadSpawn(
                FfiConverterString.read(buf),
                )
            3 -> CoreInitException.DbOpen(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreInitException): ULong {
        return when(value) {
            is CoreInitException.BadIdentity -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreInitException.ThreadSpawn -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
            is CoreInitException.DbOpen -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: CoreInitException, buf: ByteBuffer) {
        when(value) {
            is CoreInitException.BadIdentity -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreInitException.ThreadSpawn -> {
                buf.putInt(2)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
            is CoreInitException.DbOpen -> {
                buf.putInt(3)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Why a [`UniffiHttpFetch`] call failed to complete. A bare `String` is not
 * a UniFFI-throwable type (codegen rejects it), so the message travels in
 * this single-variant enum — `HttpFetchAdapter` flattens it back to the
 * plain string the `HttpFetch` port carries. The field is named `detail`
 * like every other error here: a `message` field collides with Kotlin's
 * own `Exception.message` in the generated subclass.
 */
sealed class UniffiHttpException: kotlin.Exception() {
    
    class Failed(
        
        val `detail`: kotlin.String
        ) : UniffiHttpException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<UniffiHttpException> {
        override fun lift(error_buf: RustBuffer.ByValue): UniffiHttpException = FfiConverterTypeUniffiHttpError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeUniffiHttpError : FfiConverterRustBuffer<UniffiHttpException> {
    override fun read(buf: ByteBuffer): UniffiHttpException {
        

        return when(buf.getInt()) {
            1 -> UniffiHttpException.Failed(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: UniffiHttpException): ULong {
        return when(value) {
            is UniffiHttpException.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: UniffiHttpException, buf: ByteBuffer) {
        when(value) {
            is UniffiHttpException.Failed -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



sealed class UniffiIntent {
    
    data class SendInput(
        val `machine`: kotlin.String, 
        val `sessionId`: kotlin.String, 
        val `text`: kotlin.String, 
        val `inputId`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    /**
     * Attach an image to `session_id`'s next input (CDX-029). The loop
     * uploads it to the configured Blossom server through the `UniffiHttpFetch`
     * port, falling back to relay chunks, then publishes the `upload-image`
     * command — no outbox item, no local echo (the transcript shows it once
     * the bridge injects it, like any other output).
     */
    data class SendSessionImage(
        val `machine`: kotlin.String, 
        val `sessionId`: kotlin.String, 
        /**
         * Caption carried on the input the bridge runs after the upload.
         */
        val `text`: kotlin.String, 
        /**
         * Raw image bytes (a Kotlin `ByteArray` across the FFI).
         */
        val `image`: kotlin.ByteArray, 
        val `filename`: kotlin.String, 
        /**
         * IANA media type of `image` (e.g. `"image/png"`), forwarded to the
         * bridge verbatim — the attachment command carries it as-is.
         */
        val `mimeType`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    data class Interrupt(
        val `machine`: kotlin.String, 
        val `sessionId`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    data class CloseSession(
        val `machine`: kotlin.String, 
        val `sessionId`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    data class RefreshSessions(
        val `machine`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    /**
     * Start a session on `agent` (a `UniffiAgent.id` the machine advertises).
     * `mode` / `effort` are agent-defined ids; absent = the agent's default.
     */
    data class CreateSession(
        val `machine`: kotlin.String, 
        val `agent`: kotlin.String, 
        val `cwd`: kotlin.String?, 
        val `createCwd`: kotlin.Boolean?, 
        val `mode`: kotlin.String?, 
        val `effort`: kotlin.String?, 
        val `model`: kotlin.String?, 
        val `providerId`: kotlin.String?) : UniffiIntent() {
        companion object
    }
    
    /**
     * Ask the bridge for `agent`'s live model list; the answer lands in the
     * machine's `models` entry for that agent.
     */
    data class RequestModels(
        val `machine`: kotlin.String, 
        val `agent`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    /**
     * Ask the bridge for this session's usage snapshot (limit windows, cost);
     * the answer lands in `UniffiSessionSummary.usage`.
     */
    data class RequestUsage(
        val `machine`: kotlin.String, 
        val `sessionId`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    /**
     * Ask the bridge for this session's GSD workflow state; the answer
     * lands in `UniffiSessionSummary.gsd`.
     */
    data class RequestGsd(
        val `machine`: kotlin.String, 
        val `sessionId`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    data class RequestProviderProfiles(
        val `machine`: kotlin.String) : UniffiIntent() {
        companion object
    }
    
    /**
     * Store credentials on the bridge host (CDX-011) for `agent`, or for the
     * bridge itself when `None`. Ids not listed are kept. Secrets: never
     * logged.
     */
    data class SetCredentials(
        val `machine`: kotlin.String, 
        val `agent`: kotlin.String?, 
        val `values`: List<UniffiCredentialWrite>) : UniffiIntent() {
        companion object
    }
    
    /**
     * Upsert (`profile: Some`) or delete (`profile: None`) one custom
