sealed class UniffiIntentException: kotlin.Exception() {
    
    class BadEnumValue(
        
        val `detail`: kotlin.String
        ) : UniffiIntentException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<UniffiIntentException> {
        override fun lift(error_buf: RustBuffer.ByValue): UniffiIntentException = FfiConverterTypeUniffiIntentError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeUniffiIntentError : FfiConverterRustBuffer<UniffiIntentException> {
    override fun read(buf: ByteBuffer): UniffiIntentException {
        

        return when(buf.getInt()) {
            1 -> UniffiIntentException.BadEnumValue(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: UniffiIntentException): ULong {
        return when(value) {
            is UniffiIntentException.BadEnumValue -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`detail`)
            )
        }
    }

    override fun write(value: UniffiIntentException, buf: ByteBuffer) {
        when(value) {
            is UniffiIntentException.BadEnumValue -> {
                buf.putInt(1)
                FfiConverterString.write(value.`detail`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * A UniFFI-crossable mirror of [`protocol::tristate::Tristate`] — see that
 * type's own doc comment for the keep/clear/set semantics this preserves.
 * `uniffi::Enum` needs a concrete Rust type (no generics), hence the `String`
 * payload rather than reusing `Tristate<T>` directly; every current use
 * (`SetCredentials`, `SetProviderProfile`'s `auth_token`) is string-valued on
 * the wire.
 */
sealed class UniffiTristate {
    
    object Keep : UniffiTristate()
    
    
    object Clear : UniffiTristate()
    
    
    data class Set(
        val `value`: kotlin.String) : UniffiTristate() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeUniffiTristate : FfiConverterRustBuffer<UniffiTristate>{
    override fun read(buf: ByteBuffer): UniffiTristate {
        return when(buf.getInt()) {
            1 -> UniffiTristate.Keep
            2 -> UniffiTristate.Clear
            3 -> UniffiTristate.Set(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: UniffiTristate) = when(value) {
        is UniffiTristate.Keep -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is UniffiTristate.Clear -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is UniffiTristate.Set -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`value`)
            )
        }
    }

    override fun write(value: UniffiTristate, buf: ByteBuffer) {
        when(value) {
            is UniffiTristate.Keep -> {
                buf.putInt(1)
                Unit
            }
            is UniffiTristate.Clear -> {
                buf.putInt(2)
                Unit
            }
            is UniffiTristate.Set -> {
                buf.putInt(3)
                FfiConverterString.write(value.`value`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






